<!doctype html><html lang="lt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MYGAME – Verslo operacijos</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="topbar"><div><b>MYGAME</b><span>Verslo operacijos</span></div><div class="topstats"><a href="dashboard.php">← Dashboard</a><a href="loans.php">🏦 Bankai</a></div></div><main class="page"><div class="intro"><span class="eyebrow">VALDYMAS</span><h1>Verslo operacijos</h1><p>Patalpos, darbuotojai, prekės, tiekimas, kainodara ir marketingas.</p></div><?php if($notice):?><div class="loan-alert good"><?=htmlspecialchars($notice)?></div><?php endif;?><?php if($error):?><div class="loan-alert bad"><?=htmlspecialchars($error)?></div><?php endif;?>
