<section class="card ops-card"><div class="card-head"><div><small>DARBO RINKA</small><strong>Samdyti darbuotoją</strong></div></div><form class="ops-form" method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="hire"><select name="role_id"><?php foreach($data['roles'] as $r):?><option value="<?=$r['id']?>"><?=htmlspecialchars($r['name'])?> · nuo <?=number_format((float)$r['base_salary'],0)?> €</option><?php endforeach;?></select><input name="salary" value="2300" inputmode="decimal"><button class="start">Samdyti</button></form><?php foreach($data['employees'] as $e):?><div class="ops-row"><span><b><?=htmlspecialchars($e['full_name'])?></b><small><?=htmlspecialchars($e['role_name'])?> · kompetencija <?=$e['skill']?>%</small></span><span><b><?=number_format((float)$e['salary'],0)?> €</b><form method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="dismiss"><button class="mini-action" name="id" value="<?=$e['id']?>">Atleisti</button></form></span></div><?php endforeach;?></section>
<section class="card ops-card"><div class="card-head"><div><small>PREKĖS</small><strong>Atsargos ir kainodara</strong></div></div><?php foreach($data['products'] as $p):?><div class="ops-row"><span><b><?=htmlspecialchars($p['name'])?></b><small><?=htmlspecialchars($p['category']??'Kita')?> · likutis <?=$p['quantity']?> · savikaina <?=number_format((float)$p['average_cost'],2)?> € · rinkos bazė <?=number_format((float)$p['base_price'],2)?> €</small></span><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="price"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input name="price" value="<?=$p['sale_price']?>"><button class="mini-action">Keisti kainą</button></form></div><?php endforeach;?></section>
<section class="card ops-card"><div class="card-head"><div><small>TIEKIMAS</small><strong>Užsakyti prekes</strong></div></div><form class="ops-form" method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="order"><select name="supplier_id"><?php foreach($data['suppliers'] as $s):?><option value="<?=$s['id']?>"><?=htmlspecialchars($s['name'])?> · <?=$s['country_code']?> · ×<?=number_format((float)$s['price_factor'],2)?> · <?=$s['delivery_days']?> d.</option><?php endforeach;?></select><select name="product_id"><?php foreach($data['products'] as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars(($p['category']??'Kita').' · '.$p['name'])?></option><?php endforeach;?></select><input name="qty" value="100" inputmode="decimal"><button class="start">Užsakyti</button></form></section>
<section class="card ops-card"><div class="card-head"><div><small>UŽSAKYMAI</small><strong>Pristatymo eiga</strong></div></div><?php if(!$data['orders']):?><p class="empty-state">Užsakymų dar nėra.</p><?php else:foreach($data['orders'] as $o):?><div class="ops-row"><span><b><?=htmlspecialchars($o['product_name'])?> · <?=htmlspecialchars($o['supplier_name'])?></b><small>Užsakyta <?=$o['ordered_at']?> · atvyksta <?=$o['arrives_at']?></small></span><span><b><?=number_format((float)$o['total_cost'],2,',',' ')?> €</b><small><?=htmlspecialchars($o['status'])?></small></span></div><?php endforeach;endif;?></section><section class="card ops-card"><div class="card-head"><div><small>MARKETINGAS</small><strong>Mėnesio reklamos biudžetas</strong></div></div><form class="ops-form" method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="marketing"><input name="budget" value="<?=htmlspecialchars((string)($data['marketing']['monthly_budget']??0))?>" inputmode="decimal"><button class="start">Išsaugoti</button></form><div class="dashboard-stat"><span>Žinomumas</span><b><?=number_format((float)($data['marketing']['brand_awareness']??50),1)?>%</b></div><div class="dashboard-stat"><span>Reputacija</span><b><?=number_format((float)($data['marketing']['reputation']??70),1)?>%</b></div></section></div></main></body></html>